        public void testSafeInteger()
        {
            var exchange = new Exchange(new HashMap<String, Object>() {{
                put( "id", "sampleex" );
            }});
            // safeInteger
            Object inputDict = helperDefaultInputDict();
            List<Object> inputList = new ArrayList<Object>(Arrays.asList("Hi", 2));
            Integer factor = 10;
            Assert(Helpers.isEqual(exchange.safeInteger(inputDict, "i"), 1));
            Assert(Helpers.isEqual(exchange.safeInteger(inputDict, "f"), 0));
            Assert(Helpers.isEqual(exchange.safeInteger(inputDict, "strNumber"), 3));
            Assert(Helpers.isEqual(exchange.safeInteger(inputList, 1), 2));
            // safeInteger2
            Assert(Helpers.isEqual(exchange.safeInteger2(inputDict, "a", "i"), 1));
            Assert(Helpers.isEqual(exchange.safeInteger2(inputDict, "a", "f"), 0));
            Assert(Helpers.isEqual(exchange.safeInteger2(inputDict, "a", "strNumber"), 3));
            Assert(Helpers.isEqual(exchange.safeInteger2(inputList, 2, 1), 2));
            // safeIntegerN
            Assert(Helpers.isEqual(exchange.safeIntegerN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "i"))), 1));
            Assert(Helpers.isEqual(exchange.safeIntegerN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "f"))), 0));
            Assert(Helpers.isEqual(exchange.safeIntegerN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "strNumber"))), 3));
            Assert(Helpers.isEqual(exchange.safeIntegerN(inputList, new ArrayList<Object>(Arrays.asList(3, 2, 1))), 2));
            // safeIntegerOmitZero
            Assert(Helpers.isEqual(exchange.safeIntegerOmitZero(inputDict, "i", (Long) null), 1));
            Assert(java.util.Objects.equals(exchange.safeIntegerOmitZero(inputDict, "f", (Long) null), null));
            Assert(Helpers.isEqual(exchange.safeIntegerOmitZero(inputDict, "strNumber", (Long) null), 3));
            Assert(Helpers.isEqual(exchange.safeIntegerOmitZero(inputList, 1, (Long) null), 2));
            // safeIntegerProduct
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "i", factor), 10));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "f", factor), 1)); // NB the result is 1
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "strNumber", factor), 30));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputList, 1, factor), 20));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "longInt", 0.000001), 123456789));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "inexistent", 0.000001, 123456789), 123456789));
            // regression: 0.5 * 0.000001 is 5e-7, the product is rendered in exponential notation and the old parseInt-based truncation returned 5 instead of 0
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "tiny", 0.000001), 0));
            // a product of 1e18 stays within fixed notation (no exponential form) and fits signed int64 range in non-JS target languages
            Assert(Helpers.isEqual(exchange.safeIntegerProduct(inputDict, "largeInt", 1000), 1000000000000000000L));
            // safeIntegerProduct2
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputDict, "a", "i", factor), 10));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputDict, "a", "f", factor), 1)); // NB the result is 1
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputDict, "a", "strNumber", factor), 30));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputList, 2, 1, factor), 20));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputDict, "a", "tiny", 0.000001), 0));
            Assert(Helpers.isEqual(exchange.safeIntegerProduct2(inputDict, "a", "largeInt", 1000), 1000000000000000000L));
            // safeIntegerProductN
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "i")), factor), 10));
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "f")), factor), 1)); // NB the result is 1
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "strNumber")), factor), 30));
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputList, new ArrayList<Object>(Arrays.asList(3, 2, 1)), factor), 20));
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "tiny")), 0.000001), 0));
            Assert(Helpers.isEqual(exchange.safeIntegerProductN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "largeInt")), 1000), 1000000000000000000L));
        }
        public void testSafeTimestamp()
        {
            var exchange = new Exchange(new HashMap<String, Object>() {{
                put( "id", "sampleex" );
            }});
            Object inputDict = helperDefaultInputDict();
            List<Object> inputList = new ArrayList<Object>(Arrays.asList("Hi", 2));
            // safeTimestamp
            Assert(Helpers.isEqual(exchange.safeTimestamp(inputDict, "i"), 1000));
            Assert(Helpers.isEqual(exchange.safeTimestamp(inputDict, "f"), 123));
            Assert(Helpers.isEqual(exchange.safeTimestamp(inputDict, "strNumber"), 3000));
            Assert(Helpers.isEqual(exchange.safeTimestamp(inputList, 1), 2000));
            // 1e15 seconds multiplied by 1000 is 1e18 ms, the largest timestamp product every language represents exactly
            Assert(Helpers.isEqual(exchange.safeTimestamp(inputDict, "largeInt"), 1000000000000000000L));
            // safeTimestamp2
            Assert(Helpers.isEqual(exchange.safeTimestamp2(inputDict, "a", "i"), 1000));
            Assert(Helpers.isEqual(exchange.safeTimestamp2(inputDict, "a", "f"), 123));
            Assert(Helpers.isEqual(exchange.safeTimestamp2(inputDict, "a", "strNumber"), 3000));
            Assert(Helpers.isEqual(exchange.safeTimestamp2(inputList, 2, 1), 2000));
            Assert(Helpers.isEqual(exchange.safeTimestamp2(inputDict, "a", "largeInt"), 1000000000000000000L));
            // safeTimestampN
            Assert(Helpers.isEqual(exchange.safeTimestampN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "i"))), 1000));
            Assert(Helpers.isEqual(exchange.safeTimestampN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "f"))), 123));
            Assert(Helpers.isEqual(exchange.safeTimestampN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "strNumber"))), 3000));
            Assert(Helpers.isEqual(exchange.safeTimestampN(inputList, new ArrayList<Object>(Arrays.asList(3, 2, 1))), 2000));
            Assert(Helpers.isEqual(exchange.safeTimestampN(inputDict, new ArrayList<Object>(Arrays.asList("a", "b", "largeInt"))), 1000000000000000000L));
        }
